DO $$
BEGIN
  CREATE TABLE IF NOT EXISTS public.categorias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo text UNIQUE NOT NULL, nome text NOT NULL, descricao text, cor text, icone text, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
  CREATE TABLE IF NOT EXISTS public.armazens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo text UNIQUE NOT NULL, nome text NOT NULL, descricao text, endereco text, cidade text, estado text, cep text, capacidade_total_kg numeric, capacidade_total_m3 numeric, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
  CREATE TABLE IF NOT EXISTS public.clientes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo text UNIQUE NOT NULL, nome text NOT NULL, nome_fantasia text, cnpj_cpf text, email text, telefone text, endereco text, cidade text, estado text, cep text, contato_nome text, contato_telefone text, contato_email text, ativo boolean NOT NULL DEFAULT true, observacoes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
  CREATE TABLE IF NOT EXISTS public.serial_numbers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo text UNIQUE NOT NULL, produto_id uuid REFERENCES public.produtos(id) ON DELETE SET NULL, lote_id uuid REFERENCES public.lotes(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'disponivel' CHECK (status IN ('disponivel','reservado','expedido','devolvido','descartado')), data_fabricacao date, data_validade date, nf_entrada text, observacoes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
END $$;